  print(f'{name:9s} RMS {np.sqrt((a*a).mean()):.5f}  peak {np.max(np.abs(a)):.4f} L/R {np.sqrt((a*a).mean(axis=0))}')
  # dominant spectral bins, E5 first lead note (after attack)
  if name=='lead' and pat==0:
    y=a[2205:7500,0]; Y=abs(np.fft.rfft(y*np.hanning(len(y)))); freq=np.fft.rfftfreq(len(y),1/sr); inds=np.argsort(Y)[-12:][::-1]
    print('  lead first note peaks:',[(round(freq[k],1),round(Y[k],1)) for k in inds[:10]])
